<script setup>
import { Head, Link, router, useForm } from '@inertiajs/vue3';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
const props=defineProps({notifications:Object,preferences:Object});
const form=useForm({in_app:props.preferences.in_app,email:props.preferences.email,application_updates:props.preferences.application_updates,job_alerts:props.preferences.job_alerts,interview_reminders:props.preferences.interview_reminders});
const icon=kind=>({new_application:'👤',application_status:'↗',interview_scheduled:'◷',interview_reminder:'⏰',job_alert:'⌕'}[kind]||'●');
</script>
<template><Head title="Notifications"/><AuthenticatedLayout><template #header><div class="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><p class="text-xs font-bold uppercase tracking-[.2em] text-[#309689]">Updates</p><h2 class="text-2xl font-bold">Notifications</h2></div><button @click="router.patch(route('notifications.read-all'))" class="rounded-lg border border-[#309689] px-4 py-2 text-sm font-bold text-[#309689]">Mark all as read</button></div></template><div class="mx-auto grid max-w-7xl gap-7 px-4 py-10 lg:grid-cols-[1fr_340px] sm:px-6 lg:px-8"><main><div v-if="$page.props.flash.success" class="mb-5 rounded-xl bg-emerald-50 p-4 text-emerald-800">{{$page.props.flash.success}}</div><div class="overflow-hidden rounded-2xl bg-white shadow-sm"><article v-for="item in notifications.data" :key="item.id" class="flex gap-4 border-b p-5" :class="{'bg-[#f2faf8]':!item.read_at}"><div class="grid size-11 shrink-0 place-items-center rounded-full bg-[#ebf5f4] text-xl text-[#309689]">{{icon(item.data.kind)}}</div><div class="min-w-0 flex-1"><div class="flex items-start justify-between gap-3"><div><h3 class="font-bold">{{item.data.title}}</h3><p class="mt-1 text-sm leading-6 text-gray-600">{{item.data.message}}</p><time class="mt-2 block text-xs text-gray-400">{{new Date(item.created_at).toLocaleString()}}</time></div><span v-if="!item.read_at" class="mt-2 size-2 shrink-0 rounded-full bg-[#309689]"></span></div><div class="mt-3 flex gap-4"><button @click="router.patch(route('notifications.read',item.id))" class="text-sm font-bold text-[#309689]">{{item.read_at?'Open':'Read and open'}}</button><button @click="router.delete(route('notifications.destroy',item.id))" class="text-sm font-bold text-red-600">Delete</button></div></div></article><p v-if="!notifications.data.length" class="p-16 text-center text-gray-500">You’re all caught up.</p></div><div class="mt-5 flex justify-center gap-2"><Link v-for="link in notifications.links" v-show="link.url" :href="link.url" class="rounded-lg border px-3 py-2 text-sm" :class="{'bg-[#309689] text-white':link.active}" v-html="link.label"/></div></main><aside><form @submit.prevent="form.patch(route('notifications.preferences'))" class="sticky top-6 rounded-2xl bg-white p-6 shadow-sm"><h3 class="text-lg font-bold">Preferences</h3><p class="mt-1 text-sm text-gray-500">Choose how you receive platform updates.</p><label v-for="item in [['in_app','In-app notifications'],['email','Email notifications'],['application_updates','Application updates'],['job_alerts','Job alert matches'],['interview_reminders','Interview reminders']]" class="mt-5 flex items-center justify-between gap-4"><span class="text-sm font-semibold">{{item[1]}}</span><input v-model="form[item[0]]" type="checkbox" class="rounded border-gray-300 text-[#309689] focus:ring-[#309689]"></label><button class="mt-7 w-full rounded-lg bg-[#309689] py-3 font-bold text-white" :disabled="form.processing">Save preferences</button></form></aside></div></AuthenticatedLayout></template>
